  `director_url` text,
  `director_update_date` datetime DEFAULT NULL,
  `docusign_status` int DEFAULT NULL,
  `customer_form_url` text,
  `website_purpose` int DEFAULT NULL,
  `customer_messages` text,
  `fk_reseller_id` int DEFAULT NULL,
  `designation` varchar(150) DEFAULT NULL,
  `Campaign_id` bigint DEFAULT NULL,
  `source_url` text,
  `summary` text,
  `companyUrl` text,
  PRIMARY KEY (`id`)
) /*!50100 TABLESPACE `innodb_system` */ ENGINE=InnoDB AUTO_INCREMENT=15056 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
