   SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
	
   if IFNULL(v_country_prefix,'') <> '' then
      set did = insert(did,1, CHAR_LENGTH(v_country_prefix),'0');
   end if;
		
		
   if did is null then
      set did = '';
   end if;

   return   did;  
end ;;
DELIMITER ;
