CREATE DEFINER=`dbteam`@`%` PROCEDURE `Reseller_create_comm_incentive_structure`(
    Reseller_ID INT,
    comm_apply INT,
    comm_info_xml LONGTEXT)
BEGIN
    	
        DECLARE v_hDoc INT; 
        DECLARE v_errcode INT; 
