 			,approve3_comments = p_approve3_comments
         where id = p_id and reseller_id = p_reseller_id;
 		
         set v_errcode = 0;
 		set v_errmsg = 'Success';
         
     
     end;
     select v_errcode as errcode, v_errmsg as errmsg;
     
 End ;;
