Begin


   DECLARE v_errcode INT;
   DECLARE v_errmsg VARCHAR(50);
			
   sp_exit:
   BEGIN
      If not Exists(select 1 from sme_reseller_company_admin_user a where a.email_id = email_id LIMIT 1) then
		
